describe('onError rejection values', () => {
  // specs/hal-engine-config-hooks/spec.md#8
  it('preserves rejection values as causes while rethrowing them', async () => {
    const existingError = new Error('existing');
    for (const reason of ['string boom', {code: 503}, undefined, existingError]) {
      const provider: AIProvider = {
        // eslint-disable-next-line require-yield
        async *sendMessage(): AsyncGenerator<MessageChunk> {
          throw reason;
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      };
      const session: ChatSession = {
        sessionId: 'test',
        userId: 'user',
        entries: [{role: 'user', content: 'hello', timestamp: '2024-01-01T00:00:00.000Z'}],
      };
      const onError = jest.fn(async (_session: ChatSession, _error: Error) => {});
      const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), undefined, {
        hooks: {onError},
      });
      const caught = await orchestrator.processMessage(session).then(
        () => ({rejected: false, reason: null}),
        (error: unknown) => ({rejected: true, reason: error})
      );
      const calls = onError.mock.calls;
      const reported = calls[0]?.[1];
      expect({caught, calls: calls.length, isError: reported instanceof Error, reported}).toEqual({
        caught: {rejected: true, reason},
        calls: 1,
        isError: true,
        reported: reason === existingError ? existingError : expect.objectContaining({cause: reason}),
      });
    }
  });
});
